const ELEMENT_PROP_KEYS = new Set(["theme","text","emphasis","resolveAt","stagger","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  text: "Less noise. More launch.",
  emphasis: "launch",
  resolveAt: 34,
  stagger: 2.2,
  accent: "#3B5BFD",
  fontFamily: "Geist",
  scale: 1,
  delay: 0,
  speed: 1,
};

type NdotResolveElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof NdotResolveBase>;

const NdotResolveInner = forwardRef<
  HTMLDivElement,
  NdotResolveElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<NdotResolve>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <NdotResolveBase
          {...(componentProps as unknown as ComponentProps<typeof NdotResolveBase>)}
        />
      </div>
    </Sequence>
  );
});

export const NdotResolve = Interactive.withSchema({
  Component: NdotResolveInner,
  componentName: "<NdotResolve>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
